export function fmt(n, decimals = 0) {
  const v = decimals ? Number(n.toFixed(decimals)) : Math.round(n);
  return v.toLocaleString('en-US');
}

export function fmtBig(n) {
  if (n >= 1e9) return `${(n / 1e9).toFixed(n / 1e9 >= 10 ? 1 : 2)} billion`;
  if (n >= 1e6) return `${(n / 1e6).toFixed(n / 1e6 >= 10 ? 0 : 1)} million`;
  if (n >= 1e4) return `${Math.round(n / 1e3)},000`;
  return Math.round(n).toLocaleString('en-US');
}

export function fmtRank(n) {
  if (n >= 1e6) return `${(n / 1e6).toFixed(n / 1e6 >= 10 ? 0 : 1)} million`;
  return Math.round(n).toLocaleString('en-US');
}

export function fmtMoney(n) {
  if (n >= 10000) return `$${(Math.round(n / 100) * 100).toLocaleString('en-US')}`;
  return `$${Math.round(n).toLocaleString('en-US')}`;
}

const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);

export function animateNumber(el, to, { decimals = 0, formatter = (v) => fmt(v, decimals), duration = 500 } = {}) {
  if (el._tween) cancelAnimationFrame(el._tween);
  const from = typeof el._value === 'number' ? el._value : 0;
  if (matchMedia('(prefers-reduced-motion: reduce)').matches || from === to) {
    el._value = to;
    el.textContent = formatter(to);
    return;
  }
  const start = performance.now();
  const step = (now) => {
    const t = Math.min(1, (now - start) / duration);
    const v = from + (to - from) * easeOutCubic(t);
    el.textContent = formatter(v);
    if (t < 1) {
      el._tween = requestAnimationFrame(step);
    } else {
      el._value = to;
      el._tween = null;
    }
  };
  el._tween = requestAnimationFrame(step);
}

// Approximate global personal-income distribution.
// Annual income in international (PPP-adjusted) dollars, synthesized from
// World Bank Poverty & Inequality Platform and Our World in Data (2019-2023).

export const WORLD_POP = 8_100_000_000;

// [percentile, annual income] — percentile = share of the world living on less.
const DIST = [
  [0, 0],
  [2, 210],
  [5, 320],
  [10, 420],
  [20, 700],
  [30, 1000],
  [40, 1600],
  [50, 2900],
  [60, 4400],
  [70, 6800],
  [80, 10500],
  [90, 21000],
  [95, 34000],
  [98, 60000],
  [99, 90000],
  [99.5, 140000],
  [99.9, 450000],
  [100, 3000000],
];

// Income at a given percentile, interpolating linearly in log(income).
export function incomeAtPercentile(p) {
  const q = Math.min(100, Math.max(0, p));
  for (let i = 1; i < DIST.length; i++) {
    const [p1, i1] = DIST[i - 1];
    const [p2, i2] = DIST[i];
    if (q <= p2) {
      if (i1 === 0) return (q / p2) * i2; // lowest bracket: linear
      const t = (Math.log(q || 1e-9) - Math.log(p1)) / (Math.log(p2) - Math.log(p1));
      return i1 * Math.pow(i2 / i1, t);
    }
  }
  return DIST[DIST.length - 1][1];
}

// Percentile (share of the world living on less) for a given income.
export function percentileForIncome(income) {
  if (income <= 0) return 0;
  let lo = 0, hi = 100;
  for (let k = 0; k < 60; k++) {
    const mid = (lo + hi) / 2;
    if (incomeAtPercentile(mid) < income) lo = mid;
    else hi = mid;
  }
  return (lo + hi) / 2;
}

// Cost-effectiveness estimates (see sources at bottom of the page).
export const IMPACT = {
  net: 5, // one insecticide-treated bed net (Against Malaria Foundation)
  life: 5000, // one death averted (GiveWell top-charity average, 2023-24)
  dalys: 150, // one year of healthy life (DALY) averted — conservative
  vita: 1.25, // one year of vitamin A for a child (Helen Keller Intl)
  deworm: 0.75, // one year of deworming for a child (Evidence Action)
  eyes: 50, // one cataract surgery restoring sight
};

export function computeImpact(income, pct) {
  const annual = (income * pct) / 100;
  const years = 40; // a full career of giving
  return {
    annual,
    nets: annual / IMPACT.net,
    protected: (annual / IMPACT.net) * 2,
    livesYear: annual / IMPACT.life,
    livesDecade: (annual * 10) / IMPACT.life,
    lives40: (annual * years) / IMPACT.life,
    dalysDecade: (annual * 10) / IMPACT.dalys,
    dalys40: (annual * years) / IMPACT.dalys,
    deworm: annual / IMPACT.deworm,
    vita: annual / IMPACT.vita,
    eyes: annual / IMPACT.eyes,
  };
}

// A field of 1,000 dots: each dot is ~8.1 million people, sorted by income
// (poorest top-left... actually row-major, poorest first). Recolors in a wave
// radiating from "you" whenever your percentile changes.

const N = 1000;
const POOR = [92, 116, 152, 0.35];
const RICH = [245, 178, 91, 0.65];
const YOU = [255, 255, 255, 1];

export class DotField {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.dots = [];
    this.userIndex = -1;
    this.waveStart = -1;
    this.reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
    this._resize = () => this.layout();
    addEventListener('resize', this._resize);
    this.layout();
    this._loop = (t) => this.frame(t);
    requestAnimationFrame(this._loop);
  }

  layout() {
    const dpr = Math.min(2, devicePixelRatio || 1);
    const w = Math.max(240, this.canvas.parentElement.clientWidth);
    const cols = w < 480 ? 25 : 50;
    const rows = N / cols;
    const pad = 8;
    const gapX = (w - pad * 2) / cols;
    const gapY = gapX * 1.25;
    const h = gapY * rows + pad * 2;
    this.canvas.width = Math.round(w * dpr);
    this.canvas.height = Math.round(h * dpr);
    this.canvas.style.width = `${w}px`;
    this.canvas.style.height = `${h}px`;
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    this.radius = Math.max(1.5, Math.min(4, gapX * 0.28));
    this.dots = Array.from({ length: N }, (_, i) => ({
      x: pad + ((i % cols) + 0.5) * gapX,
      y: pad + (Math.floor(i / cols) + 0.5) * gapY,
      phase: Math.random() * Math.PI * 2,
      // current and target colors
      c: [...POOR],
      t: [...POOR],
    }));
  }

  setPercentile(p) {
    const idx = Math.min(N - 1, Math.max(0, Math.round((p / 100) * N)));
    for (let i = 0; i < N; i++) {
      const target = i < idx ? POOR : i === idx ? YOU : RICH;
      this.dots[i].t = target;
      if (this.reduced) this.dots[i].c = target;
    }
    this.userIndex = idx;
    this.waveStart = performance.now();
  }

  frame(now) {
    const ctx = this.ctx;
    ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    const k = this.waveStart > 0 ? ((now - this.waveStart) / 700) * N : Infinity;
    for (let i = 0; i < N; i++) {
      const d = this.dots[i];
      // wave progress for this dot: 0 -> 1
      const dist = Math.abs(i - this.userIndex);
      const prog = this.reduced ? 1 : Math.min(1, Math.max(0, (k - dist) / 60));
      for (let ch = 0; ch < 4; ch++) {
        d.c[ch] += (d.t[ch] - d.c[ch]) * (prog === 1 ? 1 : 1 - Math.pow(1 - prog, 3));
      }
      const [r, g, b, a] = d.c;
      const shimmer = this.reduced ? 1 : 0.82 + 0.18 * Math.sin(now * 0.0012 + d.phase);
      const rad = i === this.userIndex ? this.radius * (1.6 + 0.5 * Math.sin(now * 0.005)) : this.radius;
      ctx.beginPath();
      ctx.arc(d.x, d.y, rad, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(${r | 0},${g | 0},${b | 0},${(a * shimmer).toFixed(3)})`;
      ctx.fill();
    }
    requestAnimationFrame(this._loop);
  }

  destroy() {
    removeEventListener('resize', this._resize);
  }
}

import { WORLD_POP, percentileForIncome, computeImpact } from './distribution.js';
import { DotField } from './dotfield.js';
import { fmt, fmtBig, fmtRank, fmtMoney, animateNumber } from './utils.js';

const state = { income: 45000, pct: 5 };

const $ = (sel) => document.querySelector(sel);

/* ---------------- hero: malaria counter ---------------- */
(() => {
  const el = $('#malaria-count');
  const start = Date.now();
  const tick = () => {
    const deaths = Math.floor((Date.now() - start) / 1000 / 70);
    animateNumber(el, deaths, { duration: 300 });
  };
  tick();
  setInterval(tick, 1000);
})();

/* ---------------- where you stand ---------------- */
const dots = new DotField($('#dots'));

const incomeInput = $('#income-input');
const incomeSlider = $('#income-slider');

const sliderToIncome = (t) => 500 * Math.pow(2000, t / 100); // 500 .. 1,000,000
const incomeToSlider = (v) => (Math.log(v / 500) / Math.log(2000)) * 100;

function setIncome(v, fromSlider = false) {
  state.income = Math.max(500, Math.min(2000000, Math.round(v) || 500));
  incomeInput.value = state.income.toLocaleString('en-US');
  if (!fromSlider) incomeSlider.value = incomeToSlider(state.income).toFixed(2);
  update();
}

incomeSlider.addEventListener('input', () => setIncome(sliderToIncome(+incomeSlider.value), true));
incomeInput.addEventListener('change', () => setIncome(parseInt(String(incomeInput.value).replace(/[^0-9]/g, ''), 10)));

/* ---------------- giving calculator ---------------- */
const pctSlider = $('#pct-slider');
pctSlider.addEventListener('input', () => {
  state.pct = +pctSlider.value;
  update();
});
$('#pledge-1').addEventListener('click', () => setPct(1));
$('#pledge-5').addEventListener('click', () => setPct(5));
$('#pledge-10').addEventListener('click', () => setPct(10));

function setPct(p) {
  state.pct = p;
  pctSlider.value = p;
  update();
  for (const btn of document.querySelectorAll('.pledge-btn'))
    btn.classList.toggle('active', +btn.dataset.pct === p);
}

/* ---------------- translator ---------------- */
const priceInput = $('#price-input');
priceInput.addEventListener('change', () => updateTranslator());
priceInput.addEventListener('input', () => updateTranslator());

function updateTranslator() {
  const p = Math.max(0.5, Math.min(100000, parseFloat(priceInput.value) || 20));
  const nets = p / 5;
  const deworm = p / 0.75;
  const lifeShare = (p / 5000) * 100;
  $('#tr-nets').textContent = fmt(nets, nets < 10 ? 1 : 0);
  $('#tr-people').textContent = fmt(nets * 2, nets * 2 < 10 ? 1 : 0);
  $('#tr-deworm').textContent = fmt(deworm, deworm < 10 ? 1 : 0);
  $('#tr-life').textContent = lifeShare >= 1 ? fmt(lifeShare) : lifeShare.toFixed(2);
}

/* ---------------- certificate ---------------- */
const nameInput = $('#name-input');
nameInput.addEventListener('input', () => update());

/* ---------------- master update ---------------- */
function update() {
  // ---- percentile ----
  const p = percentileForIncome(state.income);
  dots.setPercentile(p);
  animateNumber($('#richer-count'), (WORLD_POP * p) / 100, { formatter: fmtBig, duration: 600 });
  $('#richer-pct').textContent = p >= 99.9 ? '99.9+' : p.toFixed(1);
  $('#rank').textContent = fmtRank(WORLD_POP * (1 - p / 100));
  $('#stand-lead').textContent =
    p >= 90
      ? `You are richer than roughly ${fmtBig((WORLD_POP * p) / 100)} people.`
      : `You are richer than about ${p.toFixed(0)}% of humanity.`;

  // ---- impact ----
  const imp = computeImpact(state.income, state.pct);
  $('#donation-annual').textContent = fmtMoney(imp.annual);
  $('#pct-display').textContent = state.pct;
  const set = (sel, v, decimals = 0) => animateNumber($(sel), v, { decimals });
  set('#r-lives-decade', imp.livesDecade, imp.livesDecade < 10 ? 1 : 0);
  set('#r-lives-40', imp.lives40, imp.lives40 < 10 ? 1 : 0);
  set('#r-nets', imp.nets, imp.nets < 10 ? 1 : 0);
  set('#r-protected', imp.protected, imp.protected < 10 ? 1 : 0);
  set('#r-deworm', imp.deworm, imp.deworm < 10 ? 1 : 0);
  set('#r-dalys', imp.dalysDecade, imp.dalysDecade < 10 ? 1 : 0);
  $('#r-dalys-note').textContent = `over a 40-year career: ${fmt(imp.dalys40)} years`;

  // ---- certificate ----
  $('#cert-name').textContent = (nameInput.value.trim() || 'A Person Who Read This Page');
  $('#cert-pct').textContent = state.pct;
  $('#cert-amount').textContent = fmtMoney(imp.annual);
  $('#cert-lives').textContent = imp.lives40 >= 1 ? fmt(imp.lives40, 0) : imp.lives40.toFixed(1);

  updateTranslator();
}

/* ---------------- scroll reveal ---------------- */
const io = new IntersectionObserver(
  (entries) => {
    for (const e of entries) if (e.isIntersecting) e.target.classList.add('visible');
  },
  { threshold: 0.12 }
);
document.querySelectorAll('.reveal').forEach((el) => io.observe(el));

/* ---------------- init ---------------- */
setIncome(state.income);
setPct(5);
updateTranslator();

:root {
  --bg: #0a0e13;
  --panel: #121822;
  --panel-2: #0e141d;
  --line: #1f2937;
  --text: #e8edf4;
  --muted: #93a0b4;
  --faint: #6b7787;
  --amber: #f5b25b;
  --amber-soft: rgba(245, 178, 91, 0.14);
  --teal: #5ecfc0;
  --poor: #5c7698;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 16px/1.65 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

main { max-width: 1080px; margin: 0 auto; padding: 0 24px; }

h1, h2, .cert-lives {
  font-family: Georgia, "Times New Roman", "Songti SC", serif;
  font-weight: 400;
  letter-spacing: 0.01em;
}

em { color: var(--amber); font-style: italic; }

/* ---------- top bar ---------- */
.topbar {
  position: sticky; top: 0; z-index: 10;
  display: flex; align-items: center; justify-content: space-between;
  max-width: 1080px; margin: 0 auto; padding: 14px 24px;
  background: rgba(10, 14, 19, 0.88);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--line);
}
.brand {
  font-family: Georgia, serif; font-size: 18px; color: var(--text);
  text-decoration: none; letter-spacing: 0.04em;
}
.topbar nav { display: flex; gap: 22px; }
.topbar nav a { color: var(--muted); text-decoration: none; font-size: 14px; }
.topbar nav a:hover { color: var(--amber); }

/* ---------- hero ---------- */
.hero { text-align: center; padding: 96px 0 72px; }
.kicker {
  text-transform: uppercase; letter-spacing: 0.22em; font-size: 12px;
  color: var(--teal); margin-bottom: 26px;
}
.hero h1 { font-size: clamp(38px, 6vw, 64px); line-height: 1.12; margin: 0 0 22px; }
.lede {
  max-width: 640px; margin: 0 auto 44px; color: var(--muted); font-size: 18px;
}
.lede strong { color: var(--text); }
.hero-stat {
  display: inline-block; padding: 22px 34px;
  border: 1px solid var(--line); border-radius: 12px;
  background: linear-gradient(180deg, var(--panel), var(--panel-2));
}
.hero-num {
  font-size: 56px; font-weight: 200; color: var(--amber);
  font-variant-numeric: tabular-nums; line-height: 1.1;
}
.hero-label { color: var(--muted); font-size: 14px; max-width: 400px; }
.footnote {
  margin-top: 18px; color: var(--faint); font-size: 12.5px; font-style: italic;
}

/* ---------- sections ---------- */
.section { padding: 64px 0 8px; }
.section-head { margin-bottom: 30px; }
.section h2 { font-size: clamp(26px, 3.6vw, 36px); margin: 0 0 10px; }
.section-sub { color: var(--muted); max-width: 620px; margin: 0; font-size: 16.5px; }

/* ---------- panels ---------- */
.panel {
  background: var(--panel); border: 1px solid var(--line); border-radius: 14px;
  padding: 26px;
}

/* ---------- where you stand ---------- */
.stand-grid {
  display: grid; grid-template-columns: 5fr 6fr; gap: 20px; align-items: stretch;
}
.control-label { display: block; font-size: 14px; color: var(--muted); margin-bottom: 8px; }
.hint { color: var(--faint); font-size: 12.5px; }

#income-input {
  width: 100%; padding: 12px 14px; font-size: 24px; color: var(--text);
  background: var(--panel-2); border: 1px solid var(--line); border-radius: 10px;
  font-variant-numeric: tabular-nums;
}
#income-input:focus { outline: 2px solid var(--amber); outline-offset: -2px; }

input[type="range"] {
  width: 100%; margin: 22px 0 6px; accent-color: var(--amber); cursor: pointer;
}
.slider-scale {
  display: flex; justify-content: space-between;
  color: var(--faint); font-size: 11.5px;
}

.rank-line { margin-top: 14px; color: var(--muted); font-size: 15px; }
.rank-line b { color: var(--text); }
.rank-note { margin-top: 18px; color: var(--faint); font-size: 12.5px; }

.dots-panel { display: flex; flex-direction: column; justify-content: center; }
#dots { display: block; width: 100%; }
.dots-legend { display: flex; flex-wrap: wrap; gap: 18px; margin-top: 16px; font-size: 13px; color: var(--muted); }
.sw { display: inline-block; width: 9px; height: 9px; border-radius: 50%; margin-right: 7px; vertical-align: 1px; }
.sw-poor { background: rgba(92, 118, 152, 0.8); }
.sw-you { background: #fff; }
.sw-rich { background: rgba(245, 178, 91, 0.85); }

/* ---------- giving calculator ---------- */
.give-controls { margin-bottom: 22px; }
.give-slider-row { max-width: 560px; }
.give-amount { font-size: 18px; color: var(--muted); margin-top: 6px; }
.give-amount b { color: var(--amber); font-size: 22px; font-variant-numeric: tabular-nums; }
.pledge-row { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 18px; }
.pledge-btn {
  padding: 9px 16px; border-radius: 999px; border: 1px solid var(--line);
  background: var(--panel-2); color: var(--muted); font-size: 14px; cursor: pointer;
}
.pledge-btn:hover { border-color: var(--amber); color: var(--text); }
.pledge-btn.active { background: var(--amber-soft); border-color: var(--amber); color: var(--amber); }

.results-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px;
}
.stat {
  background: var(--panel); border: 1px solid var(--line); border-radius: 14px;
  padding: 24px 20px; text-align: center;
}
.stat-hero {
  grid-column: span 2; background:
    radial-gradient(120% 160% at 50% -30%, var(--amber-soft), transparent 60%), var(--panel);
  border-color: rgba(245, 178, 91, 0.35);
}
.stat-num { font-size: clamp(34px, 4.5vw, 52px); font-weight: 200; color: var(--amber); font-variant-numeric: tabular-nums; line-height: 1.15; }
.stat-label { margin-top: 6px; color: var(--text); font-size: 15px; }
.stat-note { margin-top: 8px; color: var(--faint); font-size: 13px; }
.stat-note span { color: var(--muted); }

.fineprint { color: var(--faint); font-size: 13px; max-width: 720px; margin-top: 22px; }

/* ---------- translator ---------- */
.translator { max-width: 720px; }
.price-row { display: flex; align-items: center; gap: 0; margin-top: 4px; max-width: 280px; }
.currency { font-size: 24px; color: var(--muted); padding: 12px 0 12px 14px; background: var(--panel-2); border: 1px solid var(--line); border-right: 0; border-radius: 10px 0 0 10px; }
#price-input {
  flex: 1; padding: 12px 14px; font-size: 24px; color: var(--text);
  background: var(--panel-2); border: 1px solid var(--line); border-radius: 0 10px 10px 0;
  font-variant-numeric: tabular-nums; min-width: 0;
}
#price-input:focus { outline: 2px solid var(--amber); outline-offset: -2px; }
input::-webkit-outer-spin-button, input::-webkit-inner-spin-button { -webkit-appearance: none; }
input[type=number] { -moz-appearance: textfield; appearance: textfield; }

.translator-out { font-size: 18px; margin: 24px 0 6px; max-width: 640px; }
.translator-out b { color: var(--amber); font-variant-numeric: tabular-nums; }

/* ---------- objections ---------- */
.objections { display: grid; gap: 12px; }
.objections details {
  background: var(--panel); border: 1px solid var(--line); border-radius: 12px;
  padding: 4px 22px; transition: border-color 0.25s;
}
.objections details[open] { border-color: rgba(245, 178, 91, 0.4); }
.objections summary {
  cursor: pointer; padding: 16px 0; font-family: Georgia, serif; font-size: 17.5px;
  list-style: none; position: relative; color: var(--text);
}
.objections summary::marker { display: none; }
.objections summary::after {
  content: "+"; position: absolute; right: 4px; color: var(--amber); font-size: 20px;
  transition: transform 0.25s;
}
.objections details[open] summary::after { transform: rotate(45deg); }
.objections details p { color: var(--muted); margin: 0 0 20px; max-width: 720px; }
.objections details p em { color: var(--text); font-style: italic; }

/* ---------- certificate ---------- */
.certificate {
  max-width: 640px; margin: 0 auto; text-align: center;
  border: 1px solid rgba(245, 178, 91, 0.5); border-radius: 4px;
  padding: 44px 36px 36px; background: var(--panel-2);
  box-shadow: 0 0 0 6px var(--bg), 0 0 0 7px var(--line);
}
.cert-ornament { color: var(--amber); font-size: 22px; margin-bottom: 14px; }
.cert-line { font-family: Georgia, serif; font-size: 19px; margin: 8px 0; color: var(--text); }
.cert-line b { color: var(--amber); }
.cert-close { color: var(--muted); margin-top: 20px; font-size: 16px; }
.cert-lives { font-size: clamp(40px, 6vw, 58px); color: var(--amber); margin: 4px 0 8px; font-weight: 400; }
.cert-lives b { font-variant-numeric: tabular-nums; }
#name-input {
  margin-top: 20px; padding: 11px 14px; width: min(300px, 100%);
  background: var(--panel); border: 1px solid var(--line); border-radius: 8px;
  color: var(--text); font-size: 15px; text-align: center;
}
#name-input:focus { outline: 2px solid var(--amber); outline-offset: -2px; }
.cert-note { color: var(--faint); font-size: 12.5px; margin-top: 16px; font-style: italic; }

/* ---------- sources ---------- */
.sources ul { color: var(--muted); max-width: 760px; padding-left: 20px; font-size: 14px; }
.sources li { margin-bottom: 10px; }
.sources b { color: var(--text); }

footer {
  margin-top: 70px; padding: 30px 24px 44px; text-align: center;
  border-top: 1px solid var(--line); color: var(--faint); font-size: 13.5px;
}

/* ---------- reveal ---------- */
